INSERT INTO `soal` VALUES ('15','11','15','Diketahui  f (x) = 6x &ndash; 3, g(x) = 5x + 4 dan (f o g) (a) = 81, maka nilai a adalah&hellip;','1','2','3','4','5','6','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('16','11','16','<p>Diketahui fungsi komposisi ( g o f )(x) = 4x + 5 .Jika g(x) = 2x-3, maka nilai dari f (-1) adalah&hellip;.</p>','1','<p>0</p>','<p>1</p>','<p>2</p>','<p>3</p>','<p>4</p>','C','','','','','','','');
INSERT INTO `soal` VALUES ('17','11','17','Diketahui fungsi komposisi ( f o g ) (x) = 3x + 5 dan fungsi g (x) = x -1. Tentukanlah fungsi f (x)!','1','3x +8','3x +3','3x -1','3x + 1','x +3','A',NULL,'','','','','','');
