INSERT INTO `soal` VALUES ('19','11','19','<p>Fungsi f dinyatakan oleh f(x) = 2x &ndash; 6.Jika <img src=\"data:image/png;base64,\" /> invers fungsi f , invers f(x) adalah&hellip;.</p>','1','<p><img src=\"data:image/png;base64,\" /></p>','<p><img src=\"data:image/png;base64,\" /></p>','<p><img src=\"data:image/png;base64,\" /></p>','<p><img src=\"data:image/png;base64,\" /></p>','<p><img src=\"data:image/png;base64,\" /></p>','B','','','','','','','');
INSERT INTO `soal` VALUES ('20','11','20','<p>Diketahui fungsi f dan g dalam bentuk himpunan pasangn terurut sebagai berikut:</p>\r\n<p>f ={(0,1), (1,-1), (2,2), (3,5)}</p>\r\n<p>g ={(0,2), (1,3), (2,0), (3,1)}</p>\r\n<p>hasil dari <img src=\"data:image/png;base64,\" /> adalah&hellip;.</p>','1','<p>0</p>','<p>1</p>','<p>2</p>','<p>3</p>','<p>5</p>','E','','','','','','','');
INSERT INTO `soal` VALUES ('21','11','21','Fungsi f dinyatakan oleh f(x) = 3x + 4 . Jika f-1  invers fungsi f, nilai f-1(16) adalah&hellip;.','1','-4','-2','1','2','4','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('22','11','22','Diketahui barisan aritmatika dengan suku ke- 15 dan suku ke-23  berturut- turut 20 dan 52.maka suku ke-50 adalah&hellip;.','1','100','112','120','124','160','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('23','11','23','Rasio suatu barisan geometri adalah 3 dan suku ke 8 adalah 648 maka suku ke-5 barisan tersebut adalah&hellip;.','1','24','30','120','150','180','A',NULL,'','','','','','');
