INSERT INTO `soal` VALUES ('365','46','15','Logo yang dibuat saat ini menggunakan bentuk-bentuk abstrak atau tidak memiliki asosiasi dengan bentuk Apapun yang ada di alam merupakan pengertian jenis logo&hellip;','1','Logo dalam bentuk kiasan (Allusive logos)','Logo dalam bentuk abstrak (Abstract logos)','Logo berupa inisial/singkatan nama (Initial letter logos)','Logo berupa nama dan gambar (Name/symbol logos)','Logo berupa nama (Name only logos)','B',NULL,'','','','','','');
