INSERT INTO `soal` VALUES ('368','46','18','Elemen apa yang penting dalam sebuah logo agar mudah dikenali oleh konsumen adalah&hellip;','1','Warna mencolok','Teks yang panjang','Banyak detail dan informasi','Ukuran yang besar','Desain yang sederhana dan unik','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('369','46','19','Manakah di bawah ini yang bukan merupakan alat untuk membuat logo secara online&hellip;','1','Microsoft Word','Canva','LogoMaker','Adobe Spark','Looka','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('370','46','20','Alasan kesederhanaan menjadi prinsip penting dalam desain logo adalah&hellip;','1','Agar logo terlihat lebih mahal','Agar logo memiliki lebih banyak detail','Agar logo hanya digunakan di website','Agar logo dapat diingat dengan mudah','Agar logo memiliki banyak warna','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('371','46','21','Jenis font seperti apa yang sebaiknya digunakan dalam sebuah logo&hellip;','1','Font yang rumit dan sulit dibaca','Font berwarna-warni','Font sederhana dan mudah dibaca','Font yang hanya berupa simbol','Font yang memiliki banyak variasi ukuran','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('372','46','22','Apa yang dimaksud dengan vector dalam konteks desain logo?','1','Gambar yang berbasis piksel','Gambar dengan warna yang terbatas','Gambar yang hanya berformat JPEG','Gambar yang selalu hitam-putih','Gambar yang dapat diperbesar tanpa kehilangan kualitas','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('373','46','23','Manakah format yang paling cocok untuk menyimpan logo dalam bentuk gambar&hellip;','1','PNG','DOC','GIF','BMP','XLS','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('374','46','24','Apa peran warna dalam desain logo&hellip;','1','Warna tidak mempengaruhi kesan merek','Warna hanya berguna untuk estetika','Warna harus selalu terang','Warna tidak perlu dipertimbangkan','Warna dapat menciptakan asosiasi emosional dengan merek','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('375','46','25','Apa yang harus dihindari saat mendesain logo secara online&hellip;','1','Menggunakan font sederhana','Membuat desain yang unik','Menggunakan terlalu banyak warna dan detail','Memilih kombinasi warna yang kontras','Menyimpan logo dalam format vector','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('376','46','26','Manfaat menggunakan template logo di platform online seperti Canva adalah&hellip;','1','Memungkinkan untuk mendesain logo dari nol','Menghasilkan logo yang identik dengan pesaing','Mengurangi kreativitas dalam desain','Memberikan desain dasar yang bisa disesuaikan','Menghapus elemen kustomisasi','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('377','46','27','Apakah penting untuk mempertimbangkan audiens target saat membuat logo&hellip;','1','Ya, logo harus mencerminkan identitas yang disukai audiens','Tidak, logo hanya untuk dilihat pemilik bisnis','Tidak, audiens tidak peduli dengan desain logo','Tidak, logo harus hanya mencerminkan produk','Ya, tetapi hanya jika bisnis besar','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('378','46','28','Mengapa penting untuk menyimpan logo dalam berbagai format (JPEG, PNG, SVG)&hellip;','1','Agar bisa digunakan dalam berbagai media dan ukuran','Agar bisa disimpan lebih dari satu kali','Untuk membuat lebih banyak varian logo','Agar terlihat bagus hanya di website','Untuk menambah jumlah file yang disimpan','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('379','46','29','Berikut ini yang bukan prinsip utama dalam mendesain logo yaitu&hellip;','1','Kesederhanaan','Kerelevanan','Konsistensi','Kekacauan','Keseimbangan','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('380','46','30','Alasan logo harus dapat digunakan dalam berbagai ukuran yaitu&hellip;','1','Agar lebih banyak warna yang bisa digunakan','Agar logo tetap jelas dan mudah dikenali di semua media','Agar logo bisa dicetak dengan detail kecil','Agar logo terlihat berbeda-beda di setiap media','Agar logo terlihat bagus hanya di layar besar','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('381','52','1','Yang dimaksud dengan sistem dropship dalam bisnis online adalah&hellip;','1','Penjual membeli dan menyimpan stok barang di gudangnya sendiri','Penjual menjual produk orang lain tanpa harus menyimpan stok barang','Penjual memproduksi barangnya sendiri','Penjual mengirim barang ke supplier','Pembeli menjadi produsen barang','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('382','52','2','Keuntungan utama menjadi dropshipper adalah&hellip;','1','Tidak perlu modal besar untuk membeli stok barang','Bisa memproduksi barang sendiri','Mendapatkan keuntungan dari biaya produksi','Memiliki kendali penuh atas pengiriman barang','Bisa menentukan harga supplier','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('383','52','3','Bagaimana penggunaan visual seperti gambar atau grafik dapat meningkatkan kualitas konten?','1','Menambah berat badan konten','Meningkatkan daya tarik visual dan memudahkan pemahaman','Menyulitkan pembaca untuk fokus','Mengurangi kepercayaan pembaca','Tidak memberikan nilai tambah','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('384','52','4','Apa yang merupakan syarat utama konten yang baik untuk di upload di media sosial?','1','Kuantitas kata yang banyak','Relevansi dan kualitas informasi','Tidak ada kejelasan dalam pesan','Penggunaan bahasa formal yang sulit dimengerti','Tidak memperhatikan audiens','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('385','52','5','Hal apa yang harus ada dalam konten agar mudah dipahami oleh audiens?','1','Penggunaan kata-kata sulit','Kalimat yang rumit','Struktur yang tidak teratur','Informasi yang jelas dan terstruktur','Pemilihan kata tanpa pertimbangan','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('386','52','6','Salah satu keuntungan besar dari online ritel adalah:','1','Keterbatasan dalam pilihan produk','Kemungkinan harga yang lebih tinggi','Kemudahan membandingkan harga produk dari berbagai penjual','Terbatasnya metode pembayaran','Kurangnya informasi produk yang tersedia','C',NULL,'','','','','','');
