INSERT INTO `soal` VALUES ('587','13','6','Berikut ini yang bukan merupakan termasuk pada ruang lingkup sejarah adalah,&hellip;','1','Cerita','Seni','Kisah','Peristiwa','Ilmu','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('588','13','7','Sejarah memiliki sifat unik karena pada hakikatnya suatu peristiwa sejarah tidak dapat terulang atau terjadi lagi sama persis. Dengan demikian, sejarah memiliki posisi sebagai &hellip;.','1','Pelajaran','Peristiwa','Kisah','Seni','Ilmu','B',NULL,'','','','','','');
