INSERT INTO `soal` VALUES ('590','13','9','Dibawah ini yang bukan merupakan ciri-ciri sejarah sebagai peristiwa adalah&hellip;','1','Kesenian','Unik','Abadi','Penting','Objektif','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('591','13','10','Sejarah Sebagai Peristiwa juga disebut sebagai&hellip;','1','Objektif','Subjektif','Rekreatif','Inspiratif','Sebagai kisah','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('592','13','11','Apakah yang dimaksud dengan ruang lingkup sejarah sebagai kisah&hellip;.','1','Menunjukkan peristiwa yang benar-benar terjadi pada masa lampau','Peristiwa masa lampau yang diceritakan sendiri oleh pelakunya','Peristiwa atau kejadian yang sudah tidak mungkin terjadi lagi','Peristiwa masa lampau yang telah disusun menjadi tulisan atau buku','Pengetahuan masa lampau yang berkembang dalam tradisi lisan','E',NULL,'','','','','','');
