INSERT INTO `soal` VALUES ('1237','31','6','Saat menampilkan harga produk secara online, penjual sebaiknya ...','1','Memberikan harga yang tidak sesuai','Menampilkan harga secara jelas dan sesuai kondisi penjualan','Menyembunyikan harga','Mengubah harga setiap menit tanpa alasan','Tidak mencantumkan satuan','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1238','31','7','Saat pelanggan bertanya melalui chat, penjual sebaiknya ...','1','Merespons dengan sopan, jelas, dan tepat waktu','Mengabaikan pelanggan','Membalas dengan kata-kata kasar','Meminta data pribadi yang tidak diperlukan','Mengirim pesan berulang-ulang','A',NULL,'','','','','','');
