INSERT INTO `soal` VALUES ('1240','31','9','Salah satu kelebihan pemasaran online dibandingkan offline adalah..','1','Memerlukan brosur fisik','Hanya untuk produk mahal','Hanya untuk perusahaan besar','Dapat dijangkau kapan saja dan di mana saja','Tidak butuh strategi','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1241','31','10','Untuk mengetahui keberhasilan promosi online, salah satu indikator yang dapat dianalisis adalah..','1','Jumlah meja kantor','Jumlah lampu toko','Jumlah kunjungan, interaksi, dan konversi penjualan','Warna seragam karyawan','Ukuran gudang','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1242','31','11','Dalam transaksi online, penjual perlu menjaga keamanan data pelanggan dengan cara ...','1','Menggunakan sistem yang aman dan tidak menyebarkan data pelanggan sembarangan','Membagikan nomor telepon pelanggan','Mengunggah data kartu pelanggan','Memberikan kata sandi kepada semua orang','Menyimpan data tanpa perlindungan','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1243','31','12','Kerja sama dengan influencer dalam promosi online bertujuan untuk ...','1','Menghapus merek produk','Memanfaatkan jangkauan dan pengaruh influencer terhadap audiensnya','Mengurangi informasi produk','Menggantikan kualitas produk','Menghilangkan pelayanan pelanggan','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1244','31','13','Agar promosi diskon tidak merugikan usaha, penjual harus terlebih dahulu ...','1','Mengabaikan biaya pengiriman','Menjual tanpa perhitungan','Mengikuti harga pesaing tanpa analisis','Menghapus harga pokok','Menghitung biaya dan margin keuntungan','E',NULL,'','','','','','');
